BEGIN;
SET LOCAL ROLE s2a_management;
DO $$
DECLARE u bigint; k bigint; other_key bigint; g bigint; other_group bigint; h text; other_hash text; r jsonb; job jsonb; first_lease uuid; second_lease uuid;
    task text:='imgtask_'||repeat('a',32); task2 text:='imgtask_'||repeat('b',32); task3 text:='imgtask_'||repeat('c',32); a bigint; i integer;
BEGIN
    IF has_table_privilege('service_role','s2a_private.image_tasks','SELECT') OR has_table_privilege('authenticated','s2a_private.image_tasks','SELECT')
        OR has_function_privilege('anon','public.s2a_personal_image_jobs_claim()','EXECUTE') OR has_function_privilege('authenticated','public.s2a_personal_image_job_start(text,uuid)','EXECUTE')
        OR NOT has_function_privilege('service_role','public.s2a_personal_image_task_prepare(text,text,text,text,text,text,bigint,text)','EXECUTE') THEN RAISE EXCEPTION 'image task ACL mismatch'; END IF;
    INSERT INTO public.users(email,password_hash,balance,restrict_public_groups) VALUES('image-tasks-'||gen_random_uuid()||'@example.invalid','!fixture',0,false) RETURNING id INTO u;
    INSERT INTO public.groups(name,platform) VALUES('Image task fixture','openai') RETURNING id INTO g;
    INSERT INTO public.groups(name,platform) VALUES('Other image task fixture','openai') RETURNING id INTO other_group;
    INSERT INTO public.api_keys(user_id,key,name,group_id) VALUES(u,'image-task-key-'||gen_random_uuid(),'Image fixture',g) RETURNING id,s2a_key_hash INTO k,h;
    INSERT INTO public.api_keys(user_id,key,name,group_id) VALUES(u,'other-image-task-key-'||gen_random_uuid(),'Other image fixture',g) RETURNING id,s2a_key_hash INTO other_key,other_hash;
    INSERT INTO public.accounts(name,platform,type,credentials,concurrency) VALUES('Image task account','openai','apikey','{"api_key":"fixture-image-secret"}',4) RETURNING id INTO a;
    INSERT INTO public.account_groups(account_id,group_id) VALUES(a,g),(a,other_group);
    r:=public.s2a_personal_image_task_prepare(h,task,'gpt-image-2','generations','application/json',repeat('1',64),100);
    IF r->>'status' IS DISTINCT FROM 'processing' OR r->>'object'<>'image.generation.task' OR r ? 'key_hash' OR r ? 'lease_id' OR r ? 'user_id' THEN RAISE EXCEPTION 'invalid public task view: %',r; END IF;
    IF public.s2a_personal_image_task_prepare(h,task,'gpt-image-2','generations','application/json',repeat('1',64),100) IS DISTINCT FROM r THEN RAISE EXCEPTION 'prepare replay changed task'; END IF;
    IF public.s2a_personal_image_task_prepare(h,task,'gpt-image-2','generations','application/json',repeat('2',64),100)->>'error' IS DISTINCT FROM 'image_task_conflict' THEN RAISE EXCEPTION 'request digest overwritten'; END IF;
    IF public.s2a_personal_image_task_read(other_hash,task)->>'error' IS DISTINCT FROM 'image_task_forbidden' THEN RAISE EXCEPTION 'task leaked across keys'; END IF;
    IF public.s2a_personal_image_jobs_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'uploading task claimed'; END IF;
    PERFORM public.s2a_personal_image_task_ready(h,task);
    PERFORM public.s2a_personal_image_task_ready(h,task);
    job:=public.s2a_personal_image_jobs_claim()->0;first_lease:=(job->>'lease_id')::uuid;
    IF job->>'id' IS DISTINCT FROM task OR job->>'recover'<>'false' OR job->>'body_hash' IS DISTINCT FROM repeat('1',64) OR job ? 'api_key' THEN RAISE EXCEPTION 'invalid queue claim: %',job; END IF;
    IF public.s2a_personal_image_jobs_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'task claimed twice'; END IF;
    IF public.s2a_personal_image_job_start(task,gen_random_uuid())->>'error' IS DISTINCT FROM 'image_task_lease_lost' THEN RAISE EXCEPTION 'foreign execution lease accepted'; END IF;
    IF public.s2a_personal_image_job_finish(task,first_lease,200,NULL,repeat('3',64))->>'error' IS DISTINCT FROM 'image_task_lease_lost' THEN RAISE EXCEPTION 'unstarted task completed'; END IF;
    UPDATE s2a_private.image_tasks SET lease_until=clock_timestamp()-interval '1 second' WHERE id=task;
    job:=public.s2a_personal_image_jobs_claim()->0;second_lease:=(job->>'lease_id')::uuid;
    IF job->>'recover'<>'false' OR first_lease=second_lease THEN RAISE EXCEPTION 'unstarted task was not safely re-leased'; END IF;
    IF public.s2a_personal_image_job_start(task,first_lease)->>'error' IS DISTINCT FROM 'image_task_lease_lost' THEN RAISE EXCEPTION 'old worker started'; END IF;
    IF public.s2a_personal_image_job_start(task,second_lease)->>'started' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'worker could not start'; END IF;
    IF public.s2a_personal_image_job_start(task,second_lease)->>'started' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'start replay failed'; END IF;
    IF public.s2a_personal_image_job_finish(task,second_lease,500,'provider-private-error')->>'error' IS DISTINCT FROM 'invalid_image_task_completion' THEN RAISE EXCEPTION 'provider error text accepted'; END IF;
    r:=public.s2a_personal_acquire(h,'different-model',gen_random_uuid(),p_billing_context=>jsonb_build_object('image_task',task,'image_job_lease',second_lease));
    IF r->>'error' IS DISTINCT FROM 'image_task_model_mismatch' THEN RAISE EXCEPTION 'worker model changed'; END IF;
    UPDATE public.api_keys SET group_id=other_group WHERE id=k;
    r:=public.s2a_personal_acquire(h,'gpt-image-2',gen_random_uuid(),p_billing_context=>jsonb_build_object('image_task',task,'image_job_lease',second_lease));
    IF r->>'error' IS DISTINCT FROM 'image_task_key_unavailable' THEN RAISE EXCEPTION 'worker followed changed group: %',r; END IF;
    UPDATE public.api_keys SET group_id=g WHERE id=k;
    r:=public.s2a_personal_acquire(h,'gpt-image-2',gen_random_uuid(),p_count_request=>false,p_billing_context=>jsonb_build_object('image_task',task,'image_job_lease',second_lease,'count_only',true));
    IF r ? 'error' THEN RAISE EXCEPTION 'admitted image worker could not reserve account: %',r; END IF;
    PERFORM public.s2a_personal_finish((r->>'lease_id')::uuid,200,'completed',NULL,NULL,NULL,NULL,0,1,NULL,'gpt-image-2');
    UPDATE s2a_private.image_tasks SET lease_until=clock_timestamp()-interval '1 second' WHERE id=task;
    job:=public.s2a_personal_image_jobs_claim()->0;first_lease:=(job->>'lease_id')::uuid;
    IF job->>'recover'<>'true' OR first_lease=second_lease THEN RAISE EXCEPTION 'dispatched task would be generated twice'; END IF;
    IF public.s2a_personal_image_job_start(task,first_lease)->>'error' IS DISTINCT FROM 'image_task_lease_lost' THEN RAISE EXCEPTION 'recovery worker restarted generation'; END IF;
    IF public.s2a_personal_image_job_finish(task,second_lease,200,NULL,repeat('3',64))->>'error' IS DISTINCT FROM 'image_task_lease_lost' THEN RAISE EXCEPTION 'old worker overwrote result'; END IF;
    IF public.s2a_personal_image_job_finish(task,first_lease,200,NULL,repeat('3',64))->>'applied' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'recovered result was not bound'; END IF;
    IF public.s2a_personal_image_job_finish(task,first_lease,200,NULL,repeat('3',64))->>'applied' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'result completion not idempotent'; END IF;
    IF public.s2a_personal_image_job_finish(task,first_lease,200,NULL,repeat('4',64))->>'error' IS DISTINCT FROM 'image_task_completion_conflict' THEN RAISE EXCEPTION 'completed result changed'; END IF;
    r:=public.s2a_personal_image_task_read(h,task);
    IF r->>'status'<>'completed' OR r->>'result_path'<>'images/'||task||'/result.json' OR r->>'result_hash' IS DISTINCT FROM repeat('3',64) THEN RAISE EXCEPTION 'completed view lost result'; END IF;
    PERFORM public.s2a_personal_image_task_prepare(h,task2,'gpt-image-2','edits','application/json',repeat('1',64),100);
    PERFORM public.s2a_personal_image_task_ready(h,task2);
    job:=public.s2a_personal_image_jobs_claim()->0;
    UPDATE public.api_keys SET status='inactive' WHERE id=k;
    IF public.s2a_personal_image_job_start(task2,(job->>'lease_id')::uuid)->>'error' IS DISTINCT FROM 'image_task_key_unavailable' THEN RAISE EXCEPTION 'revoked key started generation'; END IF;
    UPDATE public.api_keys SET status='active' WHERE id=k;
    IF public.s2a_personal_image_task_ready(h,task2)->>'error' IS DISTINCT FROM 'image_task_conflict' THEN RAISE EXCEPTION 'failed task resurrected'; END IF;
    PERFORM public.s2a_personal_image_task_prepare(h,task3,'gpt-image-2','generations','application/json',repeat('1',64),100);
    UPDATE s2a_private.image_tasks SET created_at=clock_timestamp()-interval '6 minutes' WHERE id=task3;
    PERFORM public.s2a_personal_image_jobs_claim();
    IF public.s2a_personal_image_task_read(h,task3)->'error'->>'code' IS DISTINCT FROM 'image_task_upload_timeout' THEN RAISE EXCEPTION 'abandoned upload did not time out'; END IF;
    UPDATE s2a_private.image_tasks SET expires_at=clock_timestamp()-interval '1 second' WHERE id=task;
    IF public.s2a_personal_image_task_read(h,task)->>'error' IS DISTINCT FROM 'image_task_not_found' THEN RAISE EXCEPTION 'expired image result visible'; END IF;
    FOR i IN 1..4 LOOP
        r:=public.s2a_personal_image_task_prepare(h,'imgtask_'||repeat(i::text,32),'gpt-image-2','generations','application/json',repeat('1',64),100);
        IF r->>'id' IS NULL THEN RAISE EXCEPTION 'queue capacity rejected admitted task: %',r; END IF;
    END LOOP;
    IF public.s2a_personal_image_task_prepare(h,'imgtask_'||repeat('5',32),'gpt-image-2','generations','application/json',repeat('1',64),100)->>'error' IS DISTINCT FROM 'image_task_queue_full' THEN RAISE EXCEPTION 'queue admission limit ignored'; END IF;
    IF public.s2a_personal_image_task_prepare(h,'imgtask_'||repeat('1',32),'gpt-image-2','generations','application/json',repeat('1',64),100)->>'id' IS NULL THEN RAISE EXCEPTION 'queue capacity blocked idempotent replay'; END IF;
    UPDATE s2a_private.image_tasks SET state='failed',http_status=400,error_code='image_task_failed',completed_at=clock_timestamp() WHERE key_id=k AND state='uploading';
    UPDATE public.groups SET platform='grok',model_allowlist='{"enabled":true,"models":["grok-imagine-image-quality"]}' WHERE id=g;
    IF public.s2a_personal_image_task_prepare(h,'imgtask_'||repeat('6',32),'not-allowed','generations','application/json',repeat('1',64),100)->>'error' IS DISTINCT FROM 'model_not_allowed' THEN RAISE EXCEPTION 'image task model allowlist ignored'; END IF;
    IF public.s2a_personal_image_task_prepare(h,'imgtask_'||repeat('6',32),'grok-imagine','generations','application/json',repeat('1',64),100)->>'id' IS NULL THEN RAISE EXCEPTION 'canonical Grok alias not admitted'; END IF;
    IF has_function_privilege('anon','public.s2a_personal_image_cleanup_claim()','EXECUTE') OR has_function_privilege('authenticated','public.s2a_personal_image_cleanup_finish(text,uuid)','EXECUTE') THEN RAISE EXCEPTION 'cleanup privileges leaked'; END IF;
    IF public.s2a_personal_image_cleanup_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'cleanup claimed live or recently expired task'; END IF;
    UPDATE s2a_private.image_tasks SET expires_at=clock_timestamp()-interval '10 minutes' WHERE id=task;
    job:=public.s2a_personal_image_cleanup_claim()->0;first_lease:=(job->>'lease_id')::uuid;
    IF job->>'id' IS DISTINCT FROM task THEN RAISE EXCEPTION 'expired cleanup task not claimed'; END IF;
    IF public.s2a_personal_image_cleanup_claim()<>'[]'::jsonb THEN RAISE EXCEPTION 'cleanup task double claimed'; END IF;
    IF public.s2a_personal_image_cleanup_finish(task,gen_random_uuid()) THEN RAISE EXCEPTION 'wrong cleanup lease deleted task'; END IF;
    UPDATE s2a_private.image_tasks SET cleanup_lease_until=clock_timestamp()-interval '1 second' WHERE id=task;
    job:=public.s2a_personal_image_cleanup_claim()->0;second_lease:=(job->>'lease_id')::uuid;
    IF first_lease=second_lease OR public.s2a_personal_image_cleanup_finish(task,first_lease) THEN RAISE EXCEPTION 'stale cleanup worker deleted task'; END IF;
    IF NOT public.s2a_personal_image_cleanup_finish(task,second_lease) THEN RAISE EXCEPTION 'cleanup completion failed'; END IF;
    IF EXISTS(SELECT 1 FROM s2a_private.image_tasks WHERE id=task) THEN RAISE EXCEPTION 'cleanup completion retained task'; END IF;
END $$;
ROLLBACK;
